// Keep substations with a usable location in states we can search, best projects first.
// A state is searchable if parcel_sources.json has a free state parcel layer for it, or a paid
// nationwide provider is switched on in Settings.
const s = $('Settings').first().json;
const data = $('Get Line Watch substations').first().json;
const sources = ($input.first().json.states) || {};
const paid = String(s.paidParcelProvider || 'off');
const onlyStates = String(s.states || '').toUpperCase().split(',').map(x => x.trim()).filter(Boolean);
const confOk = String(s.locationQuality).split(',').map(x => x.trim());
const impRank = { High: 2, Medium: 1, Low: 0 };
const windowRank = { 'Open now': 0, 'Act fast': 1, 'Late': 2 };
const minImp = impRank[s.minImportance] ?? 1;
const only = String(s.onlySubstations || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);

let subs = (data.substations || []).filter(x => confOk.includes(x.confidence)
  && (!onlyStates.length || onlyStates.includes(x.state))
  && (sources[x.state] || paid !== 'off'));
subs = subs.map(x => {
  let best = null;
  for (const p of x.projects) {
    const r = impRank[p.importance] ?? 0, w = windowRank[p.window] ?? 3;
    if (!best || r > best.r || (r === best.r && w < best.w)) best = { r, w, p };
  }
  return { ...x, bestImportance: best.p.importance, bestWindow: best.p.window, bestProject: best.p.name,
           bestStageLabel: best.p.stage_label, impRank: best.r, windowRank: best.w,
           parcelSource: sources[x.state] ? 'free' : 'paid' };
}).filter(x => x.impRank >= minImp);

if (only.length) subs = subs.filter(x => only.some(o => x.id.toLowerCase() === o || x.name.toLowerCase().includes(o)));
subs.sort((a, b) => b.impRank - a.impRank || a.windowRank - b.windowRank
  || (a.confidence === 'exact' ? 0 : 1) - (b.confidence === 'exact' ? 0 : 1));
const max = Number(s.maxSubstations) || subs.length;
return subs.slice(0, max).map(x => ({ json: x }));

// Cut the square around each substation into small map tiles, one parcel lookup per tile.
// State parcel services return at most 1,000 to 2,000 parcels per lookup, so small tiles keep
// busy areas from being cut off. Paid providers take one radius search per substation instead.
const s = $('Settings').first().json;
const sources = $('Get parcel sources').first().json.states || {};
const R = Number(s.radiusMiles);
const enc = encodeURIComponent;
function freeUrl(src, env) {
  if (src.op === 'identify') {
    return `${src.url}/identify?geometry=${enc(env)}&geometryType=esriGeometryEnvelope&sr=4326&layers=${enc(src.layer || 'all:0')}`
      + `&tolerance=0&mapExtent=${enc(env)}&imageDisplay=800,800,96&returnGeometry=true&maxAllowableOffset=0.0005&f=json`;
  }
  const where = src.where || '1=1';
  return `${src.url}/query?where=${enc(where)}&geometry=${enc(env)}&geometryType=esriGeometryEnvelope&inSR=4326`
    + `&spatialRel=esriSpatialRelIntersects&outFields=${enc(src.outFields || '*')}&returnGeometry=true&outSR=4326`
    + `&geometryPrecision=6&maxAllowableOffset=0.0005&resultRecordCount=${src.max || 1000}&f=json`;
}
const out = [];
for (const it of $input.all()) {
  const { id, lat, lon, state } = it.json;
  const src = sources[state];
  if (!src) {
    out.push({ json: { subId: id, tile: 'radius', kind: 'paid', state, lat, lon, radiusMiles: R } });
    continue;
  }
  const T = Number(src.tileMiles || s.tileMiles);
  const dLat = 1 / 69.0, dLon = 1 / (69.172 * Math.cos(lat * Math.PI / 180));
  const n = Math.ceil((2 * R) / T);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const x0 = -R + i * T, y0 = -R + j * T;
      const x1 = Math.min(x0 + T, R), y1 = Math.min(y0 + T, R);
      const env = [lon + x0 * dLon, lat + y0 * dLat, lon + x1 * dLon, lat + y1 * dLat].map(v => v.toFixed(6)).join(',');
      out.push({ json: { subId: id, tile: `${i}-${j}`, kind: 'free', state, envelope: env, url: freeUrl(src, env) } });
    }
  }
}
return out;

// Tiles whose first lookup failed (dropped connection, timeout): send them again, slowly.
return $input.all().map((it, i) => ({
  json: { ...$('Make map tiles').itemMatching(i).json, firstError: String(it.json.error?.message || 'no results') },
  pairedItem: { item: i },
}));

// Turn raw parcels into one lead per landowner.
const s = $('Settings').first().json;
const R = Number(s.radiusMiles), minAcres = Number(s.minAcres);
const subs = Object.fromEntries($('Pick substations').all().map(i => [i.json.id, i.json]));
const tileCount = $('Make map tiles').all().length;

const num = v => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };
const clean = v => (v == null || v === 'Null' || v === 'null') ? '' : String(v).trim();

// Miles from the substation to the parcel's edge (0 if the substation is inside the parcel).
function milesToParcel(lat0, lon0, rings) {
  if (!rings || !rings.length) return null;
  const kx = 69.172 * Math.cos(lat0 * Math.PI / 180), ky = 69.0;
  let inside = false, best = Infinity;
  for (const ring of rings) {
    const pts = ring.map(([x, y]) => [(x - lon0) * kx, (y - lat0) * ky]);
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const [xi, yi] = pts[i], [xj, yj] = pts[j];
      if ((yi > 0) !== (yj > 0) && 0 < ((xj - xi) * (0 - yi)) / (yj - yi) + xi) inside = !inside;
      const dx = xj - xi, dy = yj - yi, L = dx * dx + dy * dy;
      let t = L ? -(xi * dx + yi * dy) / L : 0;
      t = Math.max(0, Math.min(1, t));
      best = Math.min(best, Math.hypot(xi + t * dx, yi + t * dy));
    }
  }
  return inside ? 0 : best;
}

const PUBLIC = /\b(STATE OF|COMMONWEALTH OF|COUNTY|PARISH|CITY OF|TOWN OF|VILLAGE OF|TOWNSHIP|BOROUGH OF|ISD|SCHOOL|BOARD OF EDUCATION|UNIVERSITY|COLLEGE|UNITED STATES|U S A|USA|US GOVT|BUREAU OF|FOREST SERVICE|CORPS OF ENGINEERS|NATIONAL PARK|TXDOT|DOT|DEPARTMENT|DEPT|DNR|GLO|PERMANENT SCHOOL FUND|RAILROAD|RAILWAY|R R CO|PIPELINE|WATER (DISTRICT|SUPPLY|AUTHORITY)|MUD|DRAINAGE DISTRICT|LEVEE|CONSERVANCY|CONSERVATION|CHURCH|CEMETERY|ELECTRIC|ELEC|COOPERATIVE|CO-OP|TRANSMISSION|ONCOR|AEP|CPS ENERGY|LCRA|CENTERPOINT|ENTERGY|XCEL|AMEREN|DUKE ENERGY|DOMINION|EVERGY|PACIFICORP|TENNESSEE VALLEY AUTHORITY|TVA|SOUTHWESTERN PUBLIC|POWER (CO|COMPANY|AUTHORITY|DISTRICT))\b/;
const ENERGY = /\b(SOLAR|WIND|RENEWABLE|RENEWABLES|ENERGY STORAGE|BATTERY|BESS|POWER LLC|ENERGY LLC|ENERGY LP|DATA CENTER)\b/;
function ownerType(n) {
  if (/\b(TRUST|TR|TRUSTEE|TRS)\b/.test(n)) return 'Trust';
  if (/\b(ESTATE|EST|HEIRS)\b/.test(n)) return 'Estate';
  if (/\b(LLC|L L C|INC|CORP|CORPORATION|LP|LTD|LLP|COMPANY|CO|PARTNERS|PARTNERSHIP|HOLDINGS|FAMILY LP|MINERALS|INVESTMENTS)\b/.test(n)) return 'Business';
  return 'Person';
}

// Acres from the polygon itself, for state layers without an acreage field.
function ringAcres(lat0, rings) {
  if (!rings || !rings.length) return 0;
  const kx = 69.172 * Math.cos(lat0 * Math.PI / 180), ky = 69.0;
  let sq = 0;
  for (const ring of rings) {
    let a = 0;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) a += (ring[j][0] * kx) * (ring[i][1] * ky) - (ring[i][0] * kx) * (ring[j][1] * ky);
    sq += a / 2;  // outer rings and holes have opposite signs
  }
  return Math.abs(sq) * 640;
}
const UNITS = { acres: 1, sqft: 1 / 43560, sqm: 1 / 4046.856, sqmi: 640, hectares: 2.471054 };

// One parcel record from a free state layer (field names come from parcel_sources.json).
function fromFree(r, src, sub, state) {
  const a = r.attributes || {};
  const f = src.fields || {};
  const get = (k) => { const v = f[k]; if (!v) return ''; return (Array.isArray(v) ? v : [v]).map(x => clean(a[x])).filter(Boolean).join(' '); };
  const rings = r.geometry && r.geometry.rings;
  const miles = milesToParcel(sub.lat, sub.lon, rings);
  let acres = (num(get('acres')) || 0) * (UNITS[src.areaUnits || 'acres'] || 1);
  if (!(acres > 0) && f.acres2) acres = (num(get('acres2')) || 0) * (UNITS[src.areaUnits2 || src.areaUnits || 'acres'] || 1);
  if (!(acres > 0)) acres = ringAcres(sub.lat, rings);
  const parcelId = get('parcel_id');
  return {
    miles, key: `${state}|${get('county') || sub.county}|${parcelId || clean(a.OBJECTID ?? a.objectid ?? a.FID)}`,
    owner: get('owner').toUpperCase(), careOf: get('care_of') || get('owner2'),
    acres, county: get('county') || sub.county, state,
    propId: parcelId, geoId: get('geo_id'), legal: get('legal'),
    value: num(get('value')) || 0, situs: get('situs'),
    mail1: get('mail1'), mail2: get('mail2'), mailCity: get('mail_city'),
    mailState: get('mail_state'), mailZip: get('mail_zip').slice(0, 5), taxYear: get('tax_year'),
    source: src.label,
  };
}

// Paid provider (Regrid): GeoJSON parcels with owner and mailing fields.
function paidRecords(j) { return j && j.parcels && Array.isArray(j.parcels.features) ? j.parcels.features : null; }
function fromPaid(f, sub, state) {
  const p = (f.properties && f.properties.fields) || {};
  const g = f.geometry || {};
  const rings = g.type === 'Polygon' ? g.coordinates : g.type === 'MultiPolygon' ? g.coordinates.flat() : null;
  let miles = milesToParcel(sub.lat, sub.lon, rings);
  if (miles == null && num(p.lat) != null) miles = Math.hypot((num(p.lon) - sub.lon) * 69.172 * Math.cos(sub.lat * Math.PI / 180), (num(p.lat) - sub.lat) * 69.0);
  return {
    miles, key: `${state}|${clean(p.county)}|${clean(p.parcelnumb) || clean(f.id)}`,
    owner: clean(p.owner).toUpperCase(), careOf: clean(p.owner2),
    acres: num(p.ll_gisacre) || num(p.gisacre) || ringAcres(sub.lat, rings), county: clean(p.county) || sub.county, state: clean(p.state2) || state,
    propId: clean(p.parcelnumb) || clean(f.id), geoId: '', legal: clean(p.legaldesc),
    value: num(p.parval) || 0, situs: clean(p.address),
    mail1: clean(p.mailadd), mail2: clean(p.mail_addr2), mailCity: clean(p.mail_city),
    mailState: clean(p.mail_state2), mailZip: clean(p.mail_zip).slice(0, 5), taxYear: '',
    source: 'Regrid nationwide parcels (paid)',
  };
}

const sources = $('Get parcel sources').first().json.states || {};
const parcels = new Map();
const truncated = [];
const recordsPerSub = {};
let tileErrors = 0;
$input.all().forEach((it, i) => {
  const tile = $('Make map tiles').itemMatching(i).json, sub = subs[tile.subId];
  if (!sub) return;
  let recs;
  if (tile.kind === 'paid') recs = paidRecords(it.json);
  else recs = Array.isArray(it.json.results) ? it.json.results : Array.isArray(it.json.features) ? it.json.features : null;
  if (it.json.error || !recs) { tileErrors++; return; }
  const src = sources[tile.state] || {};
  recordsPerSub[sub.id] = (recordsPerSub[sub.id] || 0) + recs.length;
  if (tile.kind === 'free' && (it.json.exceededTransferLimit || recs.length >= Number(src.max || 2000))) truncated.push(`${sub.name} tile ${tile.tile}`);
  for (const r of recs) {
    const p = tile.kind === 'paid' ? fromPaid(r, sub, tile.state) : fromFree(r, src, sub, tile.state);
    if (!p || p.miles == null || p.miles > R) continue;
    const prev = parcels.get(p.key);
    if (prev) {
      prev.subs.add(sub.id);
      prev.miles = Math.min(prev.miles, p.miles);
      continue;
    }
    p.subs = new Set([sub.id]);
    parcels.set(p.key, p);
  }
});

// Roll parcels up to owners (same name + mailing ZIP = same owner).
const owners = new Map();
let small = 0;
for (const p of parcels.values()) {
  if (!p.owner) continue;
  const k = `${p.owner}|${p.mailZip}`;
  let o = owners.get(k);
  if (!o) owners.set(k, o = { ...p, parcels: [], acres: 0, value: 0, subs: new Set(), miles: Infinity });
  o.parcels.push(p);
  o.acres += p.acres;
  o.value += p.value;
  o.miles = Math.min(o.miles, p.miles);
  p.subs.forEach(x => o.subs.add(x));
}

const windowPts = { 'Open now': 15, 'Act fast': 10, 'Late': 3 };
const leads = [];
for (const o of owners.values()) {
  if (o.acres < minAcres) { small++; continue; }
  const subList = [...o.subs].map(id => subs[id]);
  const top = subList.slice().sort((a, b) => b.impRank - a.impRank || a.windowRank - b.windowRank)[0];
  const category = PUBLIC.test(o.owner) ? 'public-or-utility' : ENERGY.test(o.owner) ? 'energy-company' : 'landowner';
  const approx = subList.some(x => x.confidence !== 'exact');
  const score = Math.round(
    Math.min(o.acres, 640) / 640 * 35 +
    Math.max(0, 1 - o.miles / R) * 30 +
    (top.bestImportance === 'High' ? 15 : 8) +
    (windowPts[top.bestWindow] ?? 3) -
    (approx ? 5 : 0));
  leads.push({
    lead_score: score,
    category,
    owner_name: o.owner,
    owner_type: category === 'public-or-utility' ? 'Public or utility' : ownerType(o.owner),
    care_of: o.careOf !== o.owner ? o.careOf : '',
    total_acres: Math.round(o.acres * 10) / 10,
    parcel_count: o.parcels.length,
    miles_to_substation: Math.round(o.miles * 100) / 100,
    county: o.county,
    state: o.state,
    substation: subList.map(x => x.name).join('; '),
    substation_id: subList[0].id,
    substation_name: subList[0].name,
    project: top.bestProject,
    project_importance: top.bestImportance,
    project_stage: top.bestStageLabel,
    timing: top.bestWindow,
    location_check: approx ? 'Substation location is approximate: GIS team to confirm' : 'Substation location confirmed',
    mail_line1: o.mail1, mail_line2: o.mail2, mail_city: o.mailCity, mail_state: o.mailState, mail_zip: o.mailZip,
    parcel_ids: o.parcels.map(p => p.geoId || p.propId).join('; '),
    prop_ids: o.parcels.map(p => p.propId).join('; '),
    market_value: o.value,
    tax_year: o.taxYear,
    data_source: o.source,
    why: `${Math.round(o.acres)} acres, ${(Math.round(o.miles * 10) / 10)} mi from ${subList[0].name} (${top.bestProject}, ${top.bestStageLabel}).`,
  });
}
// Landowners first (best score first, capped at maxLeads), then the skipped owners for reference.
const byScore = (a, b) => b.lead_score - a.lead_score;
const land = leads.filter(l => l.category === 'landowner').sort(byScore);
const other = leads.filter(l => l.category !== 'landowner').sort(byScore);
const max = Number(s.maxLeads) || land.length;
const kept = land.slice(0, max).concat(other);
const stats = { substations: Object.keys(subs).length, tiles: tileCount, tileErrors, truncatedTiles: truncated, recordsPerSub,
  parcelsInRadius: parcels.size, ownersBelowMinAcres: small, landowners: land.length, skipped: other.length, kept: kept.length };
return kept.map((l, i) => ({ json: i === 0 ? { ...l, _run_stats: JSON.stringify(stats) } : l }));

// Demo mode: made-up numbers in the 555-0100 to 555-0199 range (reserved for fiction),
// so the whole flow can be seen end to end without paying for lookups. Never dial these.
let k = 0;
const num = () => '512555' + String(100 + (k++ % 100)).padStart(4, '0');
return $input.all().map((it, i) => {
  const lead = { ...it.json };
  const r = (i * 37) % 10;
  const phones = [];
  if (r < 7) {
    phones.push({ number: num(), type: r % 2 ? 'Mobile' : 'Landline', dnc: r === 3, litigator: r === 5, person: lead.owner_name });
    if (r < 3) phones.push({ number: num(), type: 'Mobile', dnc: false, litigator: false, person: lead.owner_name });
  }
  lead.phones = phones;
  lead.phone_lookup = phones.length ? `demo: ${phones.length} found` : 'demo: no match';
  return { json: lead, pairedItem: { item: i } };
});

// Add the phone numbers the lookup found to each lead.
const leads = $('Phone lookup on?').all(0);
return $input.all().map((it, i) => {
  const pi = (Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem)?.item ?? i;
  const lead = { ...leads[pi].json };
  const phones = [];
  for (const person of (it.json.persons || [])) {
    if (person.deceased) continue;
    for (const ph of (person.phones || [])) {
      phones.push({ number: ph.number, type: ph.type, dnc: !!ph.dnc,
        litigator: !!(ph.tcpa || person.litigator), person: person.full_name || '' });
    }
  }
  lead.phones = phones;
  lead.phone_lookup = it.json.error ? 'lookup error' : (it.json.hit ? `found ${phones.length}` : 'no match');
  return { json: lead };
});

// Decide the next step for every lead.
// AI-voice calls (Wendy) need the person's prior consent under the TCPA (FCC ruling, Feb 2024),
// so cold leads go to a letter or a human caller first. Wendy only gets people who said yes.
const s = $('Settings').first().json;
const fake = ['sandbox', 'demo'].includes(s.phoneLookup) ? `YES (${s.phoneLookup})` : '';
const consent = new Set(String(s.consentedParcelIds || '').split(',').map(x => x.trim()).filter(Boolean));
const steps = {
  'wendy': 'Owner opted in: Wendy can call to qualify and book a sales call.',
  'sales-call': 'A K2 salesperson dials by hand (no AI voice, no autodialer) to introduce K2.',
  'mail-first': 'Send a letter asking the owner to call or reply if open to a lease. Replies become Wendy leads.',
  'skip: public-or-utility': 'Public, utility or railroad land: not a lease target.',
  'skip: energy-company': 'Already an energy company: may already be leased. Useful as a competition signal.',
};
const order = { 'wendy': 0, 'sales-call': 1, 'mail-first': 2 };
return $input.all().map(it => {
  const L = { ...it.json };
  const phones = L.phones || [];
  const ok = phones.filter(p => !p.dnc && !p.litigator);
  const hasConsent = String(L.parcel_ids).split('; ').some(id => consent.has(id));
  L.list = L.category !== 'landowner' ? `skip: ${L.category}` : hasConsent ? 'wendy' : ok.length ? 'sales-call' : 'mail-first';
  L.next_step = steps[L.list];
  // Someone who opted in can be called even if their number is on a Do Not Call list
  // (their consent covers K2), but never a number flagged as a known TCPA litigator.
  const pick = hasConsent ? phones.find(p => !p.litigator) : ok[0];
  L.best_phone = pick ? pick.number : '';
  L.best_phone_type = pick ? pick.type : '';
  L.phones_found = phones.length;
  L.phones_blocked = phones.length - ok.length;
  L.phones_are_fake = phones.length ? fake : '';
  L.consent = hasConsent ? 'yes' : '';
  delete L.phones;
  delete L._run_stats;
  return { json: L };
}).sort((a, b) => (order[a.json.list] ?? 3) - (order[b.json.list] ?? 3) || b.json.lead_score - a.json.lead_score);

const rows = $input.all().map(i => i.json);
const by = {};
for (const r of rows) by[r.list] = (by[r.list] || 0) + 1;
const first = $('Score parcels and owners').first();
const stats = first && first.json._run_stats ? JSON.parse(first.json._run_stats) : {};
return [{ json: { ran_at: $now.toISO(), leads: rows.length, by_next_step: by, ...stats,
  top10: rows.filter(r => r.category === 'landowner').slice(0, 10).map(r => `${r.lead_score}  ${r.owner_name}  ${r.total_acres} ac  ${r.miles_to_substation} mi  ${r.substation}`) } }];

// A compact record of this run (what each step produced), saved next to the CSV.
// The weekly report is built from it, so it never needs n8n's full execution log.
const pick = (name, branch = 0) => { try { return $(name).all(branch).map(i => i.json); } catch (e) { return []; } };
const tiles = pick('Make map tiles');
const perSub = {};
const paidTiles = tiles.filter(t => t.kind === 'paid');
const sources = (pick('Get parcel sources')[0] || {}).states || {};
const scored = pick('Score parcels and owners');
const stats0 = scored[0] && scored[0]._run_stats ? JSON.parse(scored[0]._run_stats) : {};
Object.assign(perSub, stats0.recordsPerSub || {});
const phones = pick('Make demo phones').concat(pick('Attach phones'))
  .map(p => ({ owner_name: p.owner_name, owner_type: p.owner_type, phones: p.phones || [] }));
const record = {
  settings: $('Settings').first().json,
  substations_in_line_watch: (pick('Get Line Watch substations')[0] || {}).substations?.length || 0,
  all_substations: ((pick('Get Line Watch substations')[0] || {}).substations || []).map(x => ({ id: x.id, name: x.name, state: x.state,
    county: x.county, confidence: x.confidence, project_ids: (x.projects || []).map(p => p.id), projects: x.projects })),
  parcel_sources: Object.fromEntries(Object.entries(sources).map(([k, v]) => [k, { label: v.label, note: v.note || '' }])),
  paid_tiles: paidTiles.length,
  substations: pick('Pick substations'),
  tiles: tiles.length,
  first_tiles: tiles.slice(0, 4),
  parcel_records_per_substation: perSub,
  failed_first_try: pick('Any tile failed?', 0).length,
  stats: scored[0] && scored[0]._run_stats ? JSON.parse(scored[0]._run_stats) : {},
  scored_count: scored.length,
  phones,
  leads: $input.all().map(i => i.json),
};
return [{ json: record }];
